function drawBee(b){let art=beeArt[b.type];if(!art.complete||!art.naturalWidth)return;let T=BEE_TYPES[b.type],ease=1-Math.pow(1-(b.deploy??1),3),s=ease*T.scale,bob=b.dead?Math.sin(b.fall*13)*2:Math.sin(b.phase*T.bobRate)*T.bob,sway=b.dead?0:Math.sin(b.phase*2)*.045,fall=Math.min(1,b.fall/.7);if(!b.dead&&ease>.2)beeMark(b,s,T);ctx.save();ctx.translate(b.x,b.y+bob+fall*13);ctx.rotate(sway+fall*1.35);ctx.globalAlpha=b.dead?Math.max(0,1-b.fall/2.2):1;ctx.globalCompositeOperation='source-over';ctx.drawImage(beeSprite(b.type,b.dead||b.hitFlash>0?'hurt':selection.includes(b)?'sel':'norm'),(-54*.42-BEE_PAD)*s,(-54*.53-BEE_PAD)*s,(54*.84+BEE_PAD*2)*s,(54*1.06+BEE_PAD*2)*s);ctx.restore();if(!b.dead){let top=b.y-32*T.scale,ratio=Math.max(0,b.health/b.maxHealth);ctx.fillStyle='#15371b';ctx.fillRect(b.x-12,top,24,3);ctx.fillStyle=ratio<.35?'#d94e43':'#6da844';ctx.fillRect(b.x-12,top,24*ratio,3);if(ease>.6)ctx.drawImage(badgeSprite(b.type),b.x+12,top-8,16,16)}}
